    AllahName(number: 87, name: 'الْجَامِع', transliteration: 'Al-Jami\'', meaning: 'جامع الخلق ليوم الحساب', reflection: 'يجمع الأولين والآخرين ليوم لا ريب فيه'),
    AllahName(number: 88, name: 'الْغَنِي', transliteration: 'Al-Ghani', meaning: 'الغني عن كل شيء', reflection: 'غنيّ بذاته عن العالمين والعالمون فقراء إليه'),
    AllahName(number: 89, name: 'الْمُغْنِي', transliteration: 'Al-Mughni', meaning: 'الذي يُغني من يشاء', reflection: 'يُغني الفقراء ويُرزق المحتاجين بكرمه'),
    AllahName(number: 90, name: 'الْمَانِع', transliteration: 'Al-Mani\'', meaning: 'المانع لما يشاء حفاظاً لعباده', reflection: 'يمنع ما يشاء حمايةً لعباده وحكمةً في التدبير'),
    AllahName(number: 91, name: 'الضَّار', transliteration: 'Ad-Darr', meaning: 'القادر على الإضرار بمن يستحق', reflection: 'يضرّ من يستحق الضر بحكمته ولا يضر إلا بعدل'),
    AllahName(number: 92, name: 'النَّافِع', transliteration: 'An-Nafi\'', meaning: 'الذي يُنفع من يشاء', reflection: 'النفع كله بيده يُعطيه من يشاء بفضله'),
    AllahName(number: 93, name: 'النُّور', transliteration: 'An-Nur', meaning: 'نور السماوات والأرض', reflection: 'نور الكون كله وهادي الخلق من الظلمات إلى النور'),
    AllahName(number: 94, name: 'الْهَادِي', transliteration: 'Al-Hadi', meaning: 'الهادي للحق', reflection: 'يهدي من يشاء إلى الصراط المستقيم'),
    AllahName(number: 95, name: 'الْبَدِيع', transliteration: 'Al-Badi\'', meaning: 'المبتدع للخلق على غير مثال', reflection: 'أبدع الكون بلا مثال سابق وبلا حاجة إلى مُعلِّم'),
    AllahName(number: 96, name: 'الْبَاقِي', transliteration: 'Al-Baqi', meaning: 'الباقي بعد فناء الخلق', reflection: 'وجوده أبدي لا نهاية له بعد فناء كل شيء'),
    AllahName(number: 97, name: 'الْوَارِث', transliteration: 'Al-Warith', meaning: 'الذي يرث الأرض ومن عليها', reflection: 'يرث الكون بعد فنائه وإليه يعود كل شيء'),
    AllahName(number: 98, name: 'الرَّشِيد', transliteration: 'Ar-Rashid', meaning: 'الهادي إلى الرشاد', reflection: 'يُرشد عباده إلى ما فيه صلاحهم وهداهم'),
    AllahName(number: 99, name: 'الصَّبُور', transliteration: 'As-Sabur', meaning: 'الصابر على أذى العاصين', reflection: 'يصطبر على العاصين ويُمهلهم فرصة للتوبة'),
  ];
}
